from __future__ import annotations

# Local import of q helper shape — keep as plain dicts matching generate_workshop_quests.q()


def q(item, title, sub, reward_item=None, reward_count=1, xp=25):
    return {
        "item": item,
        "title": title,
        "sub": sub,
        "reward_item": reward_item or item,
        "reward_count": reward_count,
        "xp": xp,
    }


