def merge_extras(chapters: list[dict]) -> None:
    """Append EXTRAS after each chapter's current quests (stable early IDs)."""
    for ch in chapters:
        extra = EXTRAS.get(ch["filename"])
        if extra:
            ch["quests"].extend(extra)
